insert into public.tiles (id, process_id, data) values ('t-pick-pt-test', 'pick-pt', '{"type": "test", "name": {"cs": "Test", "uk": "Тест"}, "icon": "", "order": 3, "pdf": {}, "form": {"threshold": 80, "questions": [{"id": "q1", "type": "single", "critical": false, "correctYes": true, "text": {"cs": "Do jaké cílové TE se vychystává v PT?", "uk": "У яку цільову TE відбирають у PT?"}, "options": [{"id": "a", "text": {"cs": "Přepravka", "uk": "Ящик"}, "correct": true}, {"id": "b", "text": {"cs": "Klecový vozík (RC)", "uk": "Клітковий візок (RC)"}, "correct": false}, {"id": "c", "text": {"cs": "Paleta", "uk": "Палета"}, "correct": false}]}, {"id": "q2", "type": "single", "critical": false, "correctYes": true, "text": {"cs": "Kolik objednávek smí být v jedné přepravce v PT?", "uk": "Скільки замовлень може бути в одному ящику в PT?"}, "options": [{"id": "a", "text": {"cs": "Právě jedna", "uk": "Рівно одне"}, "correct": true}, {"id": "b", "text": {"cs": "Nejvýš tři", "uk": "Не більше трьох"}, "correct": false}, {"id": "c", "text": {"cs": "Libovolně", "uk": "Будь-яка кількість"}, "correct": false}]}, {"id": "q3", "type": "yesno", "critical": false, "correctYes": true, "options": [], "text": {"cs": "Potraviny pro prodejnu (STORE) se v PT vychystávají odděleně od ostatního zboží.", "uk": "Продукти харчування для магазину (STORE) у PT відбирають окремо від інших товарів."}}, {"id": "q4", "type": "single", "critical": false, "correctYes": true, "text": {"cs": "Čím se v PT potvrzuje vychystání, když funguje PBL?", "uk": "Чим у PT підтверджують відбір, коли працює PBL?"}, "options": [{"id": "a", "text": {"cs": "Světelným kontrolérem PBL", "uk": "Світловим контролером PBL"}, "correct": true}, {"id": "b", "text": {"cs": "Jen na PC klientovi", "uk": "Лише на ПК-клієнті"}, "correct": false}, {"id": "c", "text": {"cs": "Ústně vedoucímu směny", "uk": "Усно керівнику зміни"}, "correct": false}]}, {"id": "q5", "type": "single", "critical": false, "correctYes": true, "text": {"cs": "Kdy se v PT používá MDT?", "uk": "Коли в PT використовують MDT?"}, "options": [{"id": "a", "text": {"cs": "Jen při výpadku PBL", "uk": "Лише при збої PBL"}, "correct": true}, {"id": "b", "text": {"cs": "Vždy", "uk": "Завжди"}, "correct": false}, {"id": "c", "text": {"cs": "Nikdy", "uk": "Ніколи"}, "correct": false}]}, {"id": "q6", "type": "multi", "critical": false, "correctYes": true, "text": {"cs": "Co uděláte po přihlášení na stanici PT?", "uk": "Що ви робите після входу на станцію PT?"}, "options": [{"id": "a", "text": {"cs": "Vyberu vychystávání", "uk": "Обираю відбір"}, "correct": true}, {"id": "b", "text": {"cs": "Naskenuji TE", "uk": "Сканую TE"}, "correct": true}, {"id": "c", "text": {"cs": "Vypnu světla PBL", "uk": "Вимикаю світло PBL"}, "correct": false}]}, {"id": "q7", "type": "yesno", "critical": true, "correctYes": false, "options": [], "text": {"cs": "Smíte sahat do dopravníku, když je v chodu?", "uk": "Чи можна торкатися конвеєра, коли він працює?"}}]}, "version": 1}'::jsonb) on conflict (id) do nothing;
insert into public.tiles (id, process_id, data) values ('t-pick-pt-checklist', 'pick-pt', '{"type": "checklist", "name": {"cs": "Checklist", "uk": "Чек-лист"}, "icon": "", "order": 4, "pdf": {}, "form": {"threshold": 80, "questions": [{"id": "c1", "type": "yesno", "critical": false, "correctYes": true, "options": [], "text": {"cs": "Přihlásil se na stanici PT svým osobním číslem", "uk": "Увійшов на станцію PT зі своїм особовим номером"}}, {"id": "c2", "type": "yesno", "critical": false, "correctYes": true, "options": [], "text": {"cs": "Vybral vychystávání a naskenoval TE", "uk": "Обрав відбір і відсканував TE"}}, {"id": "c3", "type": "yesno", "critical": false, "correctYes": true, "options": [], "text": {"cs": "Bral zboží podle světla PBL a potvrdil každé místo", "uk": "Брав товар за світлом PBL і підтверджував кожне місце"}}, {"id": "c4", "type": "yesno", "critical": false, "correctYes": true, "options": [], "text": {"cs": "Před potvrzením zkontroloval počet kusů", "uk": "Перед підтвердженням перевірив кількість штук"}}, {"id": "c5", "type": "yesno", "critical": true, "correctYes": true, "options": [], "text": {"cs": "Nesahal do dopravníku za chodu", "uk": "Не торкався конвеєра під час роботи"}}, {"id": "c6", "type": "yesno", "critical": false, "correctYes": true, "options": [], "text": {"cs": "Hotovou přepravku poslal dál na dopravník", "uk": "Відправив готовий ящик далі на конвеєр"}}, {"id": "c7", "type": "note", "critical": false, "correctYes": true, "options": [], "text": {"cs": "Poznámka instruktora", "uk": "Примітка інструктора"}}]}, "version": 1}'::jsonb) on conflict (id) do nothing;
